import numpy as np

def make_input(agent, prev_agent=None, objects=None, prev_objects=None, rewards=None, extra_obstacles=None):
    x = np.zeros(500)
    # wall border
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10+c)*5 + 3] = 1.0
    # agent
    r,c = agent
    x[(r*10+c)*5 + 0] = 1.0
    if prev_agent is not None:
        r,c = prev_agent
        x[(r*10+c)*5 + 4] = 1.0
    if objects:
        for (r,c) in objects:
            x[(r*10+c)*5 + 1] = 1.0
    if prev_objects:
        for (r,c) in prev_objects:
            x[(r*10+c)*5 + 4] = 1.0
    if rewards:
        for (r,c) in rewards:
            x[(r*10+c)*5 + 2] = 1.0
    if extra_obstacles:
        for (r,c) in extra_obstacles:
            x[(r*10+c)*5 + 3] = 1.0
    return x

conditions = [
    ("base_no_prev", make_input((5,4))),
    ("base_prev", make_input((5,4), prev_agent=(5,3))),
    ("ghost_right_stat", make_input((5,4), prev_agent=(5,3), objects=[(5,5)], prev_objects=[(5,5)])),
    ("ghost_right_approach", make_input((5,4), prev_agent=(5,3), objects=[(5,5)], prev_objects=[(5,6)])),
    ("reward_right", make_input((5,4), prev_agent=(5,3), rewards=[(5,5)])),
    ("wall_right", make_input((5,4), prev_agent=(5,3), extra_obstacles=[(5,5)])),
    ("base55_prev", make_input((5,5), prev_agent=(5,4))),
    ("ghost_left55_approach", make_input((5,5), prev_agent=(5,4), objects=[(5,4)], prev_objects=[(5,3)])),
]

X = np.array([x for _, x in conditions])
logits = forward(X)
action_names = ['no-op','up','down','left','right']
for (name, _), lg in zip(conditions, logits):
    am = int(np.argmax(lg))
    print(f"{name}: logits={np.round(lg,2)} argmax={action_names[am]}")
